const expanders = document.querySelectorAll(".frame .expander");

for (const expander of expanders) {
  expander.addEventListener("click", (evt) => {
    const currentSnippet = evt.currentTarget.closest(".frame");
    const snippetWrapper = currentSnippet.querySelector(
      ".code-snippet-wrapper",
    );
    if (currentSnippet.classList.contains("collapsed")) {
      snippetWrapper.style.height = `${snippetWrapper.scrollHeight}px`;
      currentSnippet.classList.remove("collapsed");
    } else {
      currentSnippet.classList.add("collapsed");
      snippetWrapper.style.height = "0px";
    }
  });
}

// init height for non-collapsed code snippets so animation will be show
// their first collapse
const nonCollapsedSnippets = document.querySelectorAll(
  ".frame:not(.collapsed) .code-snippet-wrapper",
);

for (const snippet of nonCollapsedSnippets) {
  snippet.style.height = `${snippet.scrollHeight}px`;
}

// Traceback toggle and copy functionality
const toggleTracebackView = document.getElementById("toggle-traceback-view");
const copyTraceback = document.getElementById("copy-traceback");
const plainTextTraceback = document.getElementById("plain-text-traceback");
const tracebackTextarea = document.getElementById("traceback-textarea");

if (toggleTracebackView) {
  toggleTracebackView.addEventListener("click", () => {
    if (plainTextTraceback.style.display === "none") {
      plainTextTraceback.style.display = "block";
      toggleTracebackView.textContent = "Interactive view";
    } else {
      plainTextTraceback.style.display = "none";
      toggleTracebackView.textContent = "Plaintext view";
    }
  });
}

if (copyTraceback) {
  copyTraceback.addEventListener("click", () => {
    if (tracebackTextarea) {
      tracebackTextarea.select();
      document.execCommand("copy");
    }
  });
}

